"""Expected values generated by independent reference implementations.

Generated in a scratch environment with scipy 1.18.1, numpy 2.5.4, pymannkendall 1.4.3,
pyhomogeneity, and the rank rule of the R 'trend' package for Sen's interval. See docs/STATS_AUDIT.md. These are
literal numbers, so the test suite itself needs none of those libraries.
"""

import math
import random

import pytest

from app.stats import (
    benjamini_hochberg,
    correlation_p_value,
    mann_kendall,
    ols,
    pearson,
    pettitt,
    t_critical,
    t_two_sided_p,
)

X1 = [14.2, 14.5, 14.1, 14.9, 15.0, 14.8, 15.3, 15.1, 15.6, 15.4, 15.9, 15.7, 16.1, 15.8, 16.4, 16.0, 16.6, 16.3, 16.9, 16.5]
X2 = [3, 5, 4, 5, 6, 5, 7, 8, 7, 9, 8, 10, 9, 11, 10, 12, 11, 12, 13, 12]  # heavy ties
STEP = [0.1, -0.3, 0.2, 0.0, -0.1, 0.3, -0.2, 0.1, 0.0, -0.2, 1.1, 0.9, 1.3, 1.0, 0.8, 1.2, 1.1, 0.9, 1.4, 1.0, 1.2, 0.8]

# (t, degrees of freedom, two-sided p) from scipy.stats.t
T_CASES = [
    (0.5, 3, 0.651447964848151),
    (1.0, 5, 0.3632174676491229),
    (2.0, 10, 0.07338803477074037),
    (2.5, 12.7, 0.026962953519118944),
    (3.0, 20, 0.0070758987912110894),
    (4.5, 42, 5.3007054907166564e-05),
    (6.0, 18, 1.1269971106007855e-05),
    (1.2, 1, 0.4422841232473911),
]

# (alpha, df, critical value) from scipy.stats.t.ppf
T_CRITICAL = [
    (0.05, 2, 4.302652729749462),
    (0.05, 10, 2.2281388519862744),
    (0.05, 42, 2.018081702818444),
    (0.01, 18, 2.8784404727386073),
    (0.1, 5, 2.0150483733330233),
]


@pytest.mark.parametrize(('t', 'df', 'p'), T_CASES)
def test_student_t_p_value_matches_scipy(t, df, p):
    assert t_two_sided_p(t, df) == pytest.approx(p, rel=1e-9)


@pytest.mark.parametrize(('alpha', 'df', 'crit'), T_CRITICAL)
def test_t_critical_value_matches_scipy(alpha, df, crit):
    assert t_critical(alpha, df) == pytest.approx(crit, rel=1e-9)


# name -> (series, S, z, p, Sen slope, Sen interval low, high): pymannkendall and the R 'trend' rule
MK_CASES = {
    'X1': (X1, 160.0, 5.158641191958249, 2.487484891400271e-07, 0.13333333333333303, 0.11250000000000004, 0.1499999999999999),
    'X2': (X2, 163.0, 5.290427605078699, 1.2203071819705258e-07, 0.5, 0.4444444444444444, 0.5555555555555556),
}


@pytest.mark.parametrize('name', ['X1', 'X2'])
def test_mann_kendall_and_sen_match_reference(name):
    series, s, z, p, slope, ci_low, ci_high = MK_CASES[name]
    result = mann_kendall([float(v) for v in series], ac_correct=False)
    assert result.s == s
    assert result.z == pytest.approx(z, abs=1e-12)
    assert result.p_naive == pytest.approx(p, abs=1e-12)
    assert result.sens_slope == pytest.approx(slope, abs=1e-12)
    assert result.sens_ci_low == pytest.approx(ci_low, abs=1e-12)
    assert result.sens_ci_high == pytest.approx(ci_high, abs=1e-12)


def test_ols_matches_scipy_linregress():
    years = [float(1981 + i) for i in range(20)]
    fit = ols(X1, years)
    assert fit.slope == pytest.approx(0.13105263157894737, rel=1e-10)
    assert fit.se == pytest.approx(0.009177827144935624, rel=1e-10)
    assert fit.p_value == pytest.approx(2.929739452329342e-11, abs=1e-12)
    assert fit.ci_low == pytest.approx(0.11177073224862963, rel=1e-9)
    assert fit.ci_high == pytest.approx(0.1503345309092651, rel=1e-9)
    assert fit.r2 == pytest.approx(0.9188814386825909, rel=1e-10)


def test_benjamini_hochberg_matches_scipy():
    p_values = [0.001, 0.008, 0.039, 0.041, 0.042, 0.06, 0.074, 0.205, 0.212, 0.216, 0.222, 0.251, 0.269, 0.275, 0.34, 0.341, 0.384, 0.569, 0.594, 0.696]
    assert benjamini_hochberg(p_values, q=0.05) == [True, False, False, False, False, False, False, False, False, False, False, False, False, False, False, False, False, False, False, False]


def test_correlation_p_value_matches_scipy():
    x, y = [1.2, 0.7, 2.1, 1.9, 3.3, 2.8, 3.9, 4.4, 3.1, 5.0, 4.2, 5.9], [0.9, 1.4, 1.1, 2.6, 2.0, 3.5, 2.4, 3.9, 4.5, 3.6, 5.2, 4.8]
    r = pearson(x, y)
    assert r == pytest.approx(0.7580505843883214, rel=1e-10)
    assert correlation_p_value(r, len(x)) == pytest.approx(0.004277834447848855, abs=1e-12)


def test_pettitt_matches_pyhomogeneity():
    index, p = pettitt(STEP)
    assert index == 10
    assert p == pytest.approx(min(1.0, 0.0008517126345988648), abs=1e-12)


# ---- calibration by simulation (seeded, so deterministic) -------------------------------------


def _rejection_rate(phi, trials=500, n=44, seed=11):
    rng = random.Random(seed)
    naive = adjusted = 0
    for _ in range(trials):
        x, series = rng.gauss(0, 1), []
        for _ in range(n):
            x = phi * x + math.sqrt(1 - phi * phi) * rng.gauss(0, 1)
            series.append(x)
        result = mann_kendall(series, [float(i) for i in range(n)])
        naive += result.p_naive < 0.05
        adjusted += result.p_value < 0.05
    return naive / trials, adjusted / trials


def test_independent_years_give_about_five_percent_false_alarms():
    naive, adjusted = _rejection_rate(0.0)
    assert 0.02 <= adjusted <= 0.075
    assert abs(adjusted - naive) < 0.03       # the adjustment must not cost much when there is nothing to adjust


def test_persistent_years_no_longer_trigger_many_false_alarms():
    # Nominal 5%. Without any adjustment this rate is above 20%; the corrected test stays near the nominal level.
    naive, adjusted = _rejection_rate(0.5)
    assert naive > 0.15
    assert adjusted <= 0.08


def test_a_real_trend_is_still_detected_with_independent_years():
    rng = random.Random(5)
    hits = 0
    for _ in range(200):
        series = [0.06 * i + rng.gauss(0, 1) for i in range(44)]
        hits += mann_kendall(series, [float(i) for i in range(44)]).significant
    assert hits / 200 > 0.8
